import { useRef } from 'react'
import { KJDraw, type KJDrawEditor } from '@kanjieteam/kjdraw/react'

export function DrawingEditor() {
  const editor = useRef<KJDrawEditor | null>(null)
  return (
    <KJDraw
      ref={editor}
      document="sample"
      locale="en"
      theme="dark"
      style={{ height: 720 }}
    />
  )
}
